                while q:
                    y, x = q.popleft(); cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            a, b = y + dy, x + dx
                            if 0 <= a < h and 0 <= b < w and grid[a][b] == grid[i][j] and (a, b) not in seen:
                                seen.add((a, b)); q.append((a, b))
                ys = [y for y, _ in cells]; xs = [x for _, x in cells]
                res.append((min(ys), min(xs), max(ys), max(xs)))
    return res

def _no_hmirror(crop):
    a = np.array(crop)
    return not (a[:, ::-1] == a).all()

def transform(grid):
    # output = the object that is not left-right mirror symmetric
    picks = []
